                while q:
                    x,y=q.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and grid[nx][ny] and (nx,ny) not in seen:
                            seen.add((nx,ny)); q.append((nx,ny))
                comps.append(comp)
    panel=max(comps,key=len)
    r0=min(r for r,c in panel); r1=max(r for r,c in panel)
    c0=min(c for r,c in panel); c1=max(c for r,c in panel)
    a=[row[c0:c1+1] for row in grid[r0:r1+1]]
    H,W=len(a),len(a[0])
    external={}
    for comp in comps:
        if comp is not panel and len(comp)==1:
            r,c=comp[0]; external[grid[r][c]]=(r,c)
    # Interior occurrences of the three exterior colors are the orientation anchors.
    anchors={}
    for color in external:
        pts=[(r,c) for r in range(H) for c in range(W) if a[r][c]==color]
        if pts: anchors[color]=pts[0]
    def corner(r,c,hh,ww):
        return ('T' if r < hh/2 else 'B')+('L' if c < ww/2 else 'R')
    er0=min(r for r,c in external.values()); er1=max(r for r,c in external.values())
    ec0=min(c for r,c in external.values()); ec1=max(c for r,c in external.values())
    targets={color:corner(r-er0,c-ec0,er1-er0+1,ec1-ec0+1) for color,(r,c) in external.items()}
    transforms=[
      ('id',lambda r,c:(r,c),H,W),
      ('hflip',lambda r,c:(H-1-r,c),H,W),
      ('vflip',lambda r,c:(r,W-1-c),H,W),
      ('rot180',lambda r,c:(H-1-r,W-1-c),H,W),
      ('transpose',lambda r,c:(c,r),W,H),
      ('anti',lambda r,c:(W-1-c,H-1-r),W,H),
      ('cw',lambda r,c:(c,H-1-r),W,H),
      ('ccw',lambda r,c:(W-1-c,r),W,H),
    ]
    valid=[]
    for name,fn,oh,ow in transforms:
        score=0
        for color,(r,c) in anchors.items():
            rr,cc=fn(r,c)
            if corner(rr,cc,oh,ow)==targets[color]: score+=1
        valid.append((score,name,fn,oh,ow))
    _,name,fn,oh,ow=max(valid,key=lambda x:x[0])
    offset=1 if name=='vflip' else 0
    out=[[1]*ow for _ in range(oh+offset)]
    for r in range(H):
        for c in range(W):
            rr,cc=fn(r,c); out[rr+offset][cc]=a[r][c]
    return out
